  }

  .modal-footer {
    display: flex;
    justify-content: flex-end;
  }
</style>
```

Ahora, puedes agregar los estilos y los eventos de JavaScript para que el modal se muestre y se actualice dinámicamente con los mensajes de la conversación:

```javascript
// Abre el modal con el historial de conversación
function openChatHistory() {
  document.getElementById("chat-history-modal").style.display = "block";
}

// Cierra el modal con el historial de conversación
function closeChatHistory() {
  document.getElementById("chat-history-modal").style.display = "none";
}

// Actualiza el historial de conversación con los mensajes de la conversación
function updateChatHistory(messages) {
  let chatHistory = document.getElementById("chat-history");
  chatHistory.innerHTML = "";
  for (let I = 0; I < messages.length; i++) {
    let message = messages[i];
    let messageClass = message.user ? "user-message" : "bot-message";
    let messageElement = document.createElement("p");
    messageElement.textContent = message.text;
    messageElement.classList.add(messageClass);
    chatHistory.appendChild(messageElement);
  }
}

// Agrega un nuevo mensaje a la conversación y actualiza el historial de conversación
function addChatMessage(message) {
  let chatOutput = document.getElementById("chatbot-output");
  let chatMessage = document.createElement("div");
  chatMessage.classList.add("chat-message");

  let userMessage = document.createElement("p");
  userMessage.classList.add("user-message");
  userMessage.textContent = message.text;

  let botMessage = document.createElement("p");
  botMessage.classList.add("bot-message");
  botMessage.textContent = message.response;

  chatMessage.appendChild(userMessage);
  chatMessage.appendChild(botMessage);
  chatOutput.appendChild(chatMessage);

  let chatHistory = document.getElementById("chat-history");
  let messages = chatHistory.querySelectorAll("p");
  messages.push(userMessage);
  messages.push(botMessage);

  updateChatHistory([...messages]);
}

// Maneja los eventos de envío de mensajes
document.getElementById("chatbot-send").addEventListener("click", () => {
  let input = document.getElementById("chatbot-input").value;
  let message = {
    text: input,
    user: true,
  };

  // Agrega el mensaje a la conversación y actualiza el historial de conversación
  addChatMessage(message);

  // Limpia el input de texto
  document.getElementById("chatbot-input").value = "";
});

// Agrega los primeros 4 mensajes de ejemplo
let messages = [
  { text: "Hola, ¿cómo estás?", response: "¡Gracias por preguntar! Estoy bien, ¿cómo estás tú?" },
  { text: "Me siento bien, gracias. ¿Qué puedes hacer?", response: "Puedo responder a preguntas y brindar ayuda en general. ¿Podría proporcionar más detalles sobre lo que buscas para ayudar a que nuestras conversaciones sean más relevantes?" },
  { text: "Soy nuevo aquí, ¿podrías decirme más sobre ti?", response: "Soy un chatbot de prueba, creado para ayudar a demostrar cómo se pueden crear aplicaciones de chat inteligentes. ¿Qué tipo de información te interesa saber?" },
  { text: "Me encanta cómo funciona este chatbot. ¿Podría proporcionar más información sobre su desarrollo?", response: "¡Gracias por el elogio! Este chatbot fue creado utilizando una combinación de lenguaje de marcas, APIs y servicios de inteligencia artificial. ¿Podría proporcionar más detalles sobre lo que te interesa para proporcionar más información sobre su desarrollo?" },
];

// Inicializa el historial de conversación con los primeros 4 mensajes
updateChatHistory(messages);
```

